const QUESTIONS = [{"topic":"Resuscitation","question":"An inferior STEMI patient has BP 76/42, raised JVP, clear lungs and ST elevation in V4R. Best immediate supportive intervention while arranging reperfusion?","options":["IV GTN","Cautious 250 mL crystalloid bolus with reassessment","IV furosemide","IV metoprolol"],"answer":1,"explanation":"RV infarction causes preload-dependent output. Small fluid boluses may help if no congestion; urgent reperfusion remains essential.","pearl":"Avoid preload-reducing drugs in hypotensive RV infarction.","reference":"ESC ACS guideline"},{"topic":"Resuscitation","question":"Septic shock persists at MAP 53 despite appropriate initial fluids. Preferred first-line vasopressor?","options":["Dopamine","Noradrenaline","Phenylephrine","Dobutamine alone"],"answer":1,"explanation":"Noradrenaline is preferred, initially targeting MAP approximately 65 mmHg, individualised to perfusion.","pearl":"Do not delay vasopressors in persistent shock.","reference":"Surviving Sepsis Campaign"},{"topic":"Resuscitation","question":"VF persists after three defibrillation attempts in adult cardiac arrest. Which antiarrhythmic is recommended?","options":["Amiodarone 300 mg IV/IO","Verapamil 5 mg IV","Metoprolol 5 mg IV","Atropine 1 mg IV"],"answer":0,"explanation":"Amiodarone 300 mg IV/IO is given after the third shock in standard shockable ALS algorithms. Continue CPR and address reversible causes.","pearl":"Know shockable arrest drug timing.","reference":"ANZCOR ALS"},{"topic":"Resuscitation","question":"A 35-year-old develops hypotension, bronchospasm and urticaria immediately after IV antibiotics. First-line drug?","options":["IV hydrocortisone","IM adrenaline 0.5 mg of 1 mg/mL","IV antihistamine","Nebulised salbutamol alone"],"answer":1,"explanation":"IM adrenaline into the lateral thigh is first-line for adult anaphylaxis; repeat if required and support airway and circulation.","pearl":"Antihistamines and steroids must not delay adrenaline.","reference":"ASCIA anaphylaxis guidance"},{"topic":"Resuscitation","question":"Regular broad-complex tachycardia at 190/min causes BP 65/35 and confusion. Pulse present. Immediate treatment?","options":["IV verapamil","IV adenosine and observe","Synchronized electrical cardioversion","Oral beta blocker"],"answer":2,"explanation":"Unstable tachyarrhythmia with a pulse requires immediate synchronized cardioversion, with sedation if feasible without delay.","pearl":"Physiology determines urgency.","reference":"ANZCOR peri-arrest guidance"},{"topic":"Cardiology","question":"Known WPW with irregular broad-complex tachycardia at 220/min. Which drug should be avoided?","options":["Procainamide","Verapamil","Ibutilide","Expert-guided rhythm control"],"answer":1,"explanation":"AV nodal blockers may accelerate conduction through an accessory pathway in pre-excited AF and precipitate VF.","pearl":"Avoid AV nodal blockers in pre-excited AF.","reference":"ACC/AHA AF guideline"},{"topic":"Cardiology","question":"Acute pulmonary oedema with BP 220/115 and severe respiratory distress. Best initial combination?","options":["2 L crystalloid rapidly","NIV and titrated nitrates","IV beta blocker alone","Thrombolysis"],"answer":1,"explanation":"NIV improves oxygenation and work of breathing; nitrates reduce preload and afterload in hypertensive pulmonary oedema.","pearl":"Address afterload and oxygenation simultaneously.","reference":"ESC heart failure guidance"},{"topic":"Cardiology","question":"Inferior STEMI with hypotension. Which ECG finding supports RV infarction?","options":["ST depression V1","ST elevation V4R","QT prolongation","T inversion aVL alone"],"answer":1,"explanation":"Right-sided V4R ST elevation supports RV involvement, explaining preload-sensitive hypotension.","pearl":"Obtain right-sided leads in hypotensive inferior STEMI.","reference":"ESC ACS guideline"},{"topic":"Cardiology","question":"A stable patient has sustained monomorphic VT at 160/min. Best management principle?","options":["Treat as sinus tachycardia","Monitored antiarrhythmic or planned cardioversion with expert support","Routine IV verapamil","Discharge after normal troponin"],"answer":1,"explanation":"Stable VT requires monitoring and active treatment with readiness for cardioversion. Drug choice depends on underlying cardiac function.","pearl":"Stable VT is not benign.","reference":"ESC ventricular arrhythmia guidance"},{"topic":"Cardiology","question":"Mechanical mitral valve, S. aureus bacteraemia and new murmur. Which investigation is particularly important?","options":["Exercise test","Transoesophageal echocardiography","Coronary calcium score","Holter monitor"],"answer":1,"explanation":"TOE improves detection of prosthetic valve vegetations, abscesses and complications.","pearl":"Prosthetic valve endocarditis warrants TOE.","reference":"ESC endocarditis guideline"},{"topic":"Toxicology","question":"Massive modified-release paracetamol ingestion 8 hours earlier with concentration above treatment line. Best approach?","options":["Wait until 24 hours","Charcoal only","IV acetylcysteine with serial levels and liver tests","Stop once asymptomatic"],"answer":2,"explanation":"Delayed absorption requires acetylcysteine when indicated and serial biochemical monitoring.","pearl":"A single nomogram point is insufficient for modified-release overdose follow-up.","reference":"Australia/NZ paracetamol poisoning guidance"},{"topic":"Toxicology","question":"TCA overdose with QRS 160 ms, hypotension and ventricular ectopy. First-line targeted treatment?","options":["IV sodium bicarbonate","Flumazenil","Calcium gluconate alone","Phenytoin"],"answer":0,"explanation":"Bicarbonate counteracts sodium-channel blockade; repeat guided by ECG, haemodynamics, pH and electrolytes.","pearl":"QRS widening signals serious TCA toxicity.","reference":"Clinical toxicology guidance"},{"topic":"Toxicology","question":"Salicylate toxicity with tinnitus and mixed respiratory alkalosis/metabolic acidosis. Which intervention increases renal elimination?","options":["IV sodium bicarbonate for urinary alkalinisation","Urinary acidification","Flumazenil","High-dose furosemide"],"answer":0,"explanation":"Urinary alkalinisation enhances salicylate excretion, while severe toxicity may require dialysis.","pearl":"Prevent acidaemia and correct hypokalaemia.","reference":"EXTRIP salicylate guidance"},{"topic":"Toxicology","question":"Coma, pinpoint pupils and respiratory rate 5/min after suspected opioid ingestion. Immediate priority?","options":["CT brain first","Airway and ventilation with titrated naloxone","Activated charcoal immediately","Flumazenil"],"answer":1,"explanation":"Ventilate and oxygenate first; titrate naloxone to restore adequate respiratory effort and monitor for recurrence.","pearl":"Aim for adequate breathing, not necessarily full wakefulness.","reference":"Opioid poisoning management guidance"},{"topic":"Toxicology","question":"Severe methanol toxicity with visual symptoms and anion-gap acidosis. Which drug prevents toxic metabolite production?","options":["N-acetylcysteine","Fomepizole","Atropine","Pralidoxime"],"answer":1,"explanation":"Fomepizole blocks alcohol dehydrogenase and formation of formate. Severe cases may require haemodialysis.","pearl":"Treat suspected toxic alcohol poisoning before confirmatory levels if necessary.","reference":"EXTRIP methanol guidance"},{"topic":"Paediatrics","question":"Three-year-old with life-threatening asthma has minimal air entry despite inhaled therapy and steroids. Appropriate adjunct?","options":["IV magnesium sulfate","Oral montelukast","Routine IV antibiotics","IV furosemide"],"answer":0,"explanation":"IV magnesium may help refractory severe asthma; continue bronchodilators and obtain senior critical care support.","pearl":"A silent chest is a critical warning sign.","reference":"Paediatric acute asthma guidance"},{"topic":"Paediatrics","question":"Two-year-old with fever has a 4-minute generalised seizure and returns rapidly to baseline without focal findings. Best classification?","options":["Requires CT for all cases","Simple febrile seizure","Requires chronic antiepileptic therapy","Mandatory LP"],"answer":1,"explanation":"Brief generalised seizure with full recovery and no recurrence within 24 hours fits a simple febrile seizure.","pearl":"Investigations follow clinical findings, not seizure alone.","reference":"RCH febrile seizure guidance"},{"topic":"Paediatrics","question":"Six-month-old with bronchiolitis, moderate work of breathing and SpO2 88% on room air. Initial management?","options":["Routine salbutamol","Oxygen and supportive care","Routine corticosteroids","Routine antibiotics"],"answer":1,"explanation":"Supportive care includes oxygen when indicated, hydration and airway suction as needed.","pearl":"Routine bronchodilators and steroids are not beneficial.","reference":"Australasian bronchiolitis guideline"},{"topic":"Paediatrics","question":"Four-year-old with suspected epiglottitis is drooling, stridulous and tripod-positioned. Safest approach?","options":["Force throat examination","Keep calm and arrange expert-controlled airway","Unmonitored CT neck","Use tongue depressor"],"answer":1,"explanation":"Avoid agitation or provocative examinations; obtain expert anaesthetic, ENT and paediatric support.","pearl":"Minimise distress in threatened upper airway obstruction.","reference":"Paediatric airway guidance"},{"topic":"Paediatrics","question":"Seven-year-old with DKA develops headache, bradycardia and falling GCS during treatment. Presume which complication?","options":["Hypocalcaemia","Cerebral injury/oedema","Migraine","Benign drug effect"],"answer":1,"explanation":"Neurological deterioration suggests cerebral injury; administer protocol-based hyperosmolar therapy without delaying for CT.","pearl":"Treat suspected DKA cerebral injury clinically.","reference":"ISPAD DKA guideline"},{"topic":"Trauma","question":"Blunt trauma with profound hypotension, respiratory distress and unilateral absent breath sounds. Immediate priority?","options":["Chest X-ray","Pleural decompression","CT chest","IV furosemide"],"answer":1,"explanation":"Suspected tension pneumothorax in an unstable patient requires immediate decompression without imaging delay.","pearl":"Tension pneumothorax is a clinical diagnosis.","reference":"Trauma resuscitation guidance"},{"topic":"Trauma","question":"Unstable blunt trauma patient has positive FAST. Next priority?","options":["CT abdomen first","Urgent surgical haemorrhage control and resuscitation","Discharge","Colonoscopy"],"answer":1,"explanation":"Shock with intraperitoneal free fluid strongly suggests bleeding requiring operative control.","pearl":"Do not transport unstable patients to CT unnecessarily.","reference":"ATLS principles"},{"topic":"Trauma","question":"Hypotensive patient with suspected unstable pelvic fracture needs binder placement. Correct level?","options":["Iliac crests","Greater trochanters","Lower ribs","Umbilicus"],"answer":1,"explanation":"Pelvic binders should be placed over the greater trochanters for effective mechanical reduction.","pearl":"A binder positioned too high may be ineffective.","reference":"Pelvic trauma guidance"},{"topic":"Trauma","question":"Penetrating chest trauma with shock, elevated JVP and pericardial fluid on eFAST. Priority?","options":["Urgent operative management of tamponade","IV furosemide","Outpatient echo","Beta blockade"],"answer":0,"explanation":"Traumatic tamponade needs immediate surgical management; pericardiocentesis may only temporise selected cases.","pearl":"Penetrating traumatic tamponade is a surgical emergency.","reference":"ATLS principles"},{"topic":"Trauma","question":"Trauma patient with suspected C-spine injury needs intubation for airway protection. Best principle?","options":["Wait for imaging","Manual in-line stabilisation while securing airway","Force neck extension","Avoid preoxygenation"],"answer":1,"explanation":"Prioritise oxygenation and airway management with experienced operator and spinal motion restriction.","pearl":"Spinal precautions must not compromise airway care.","reference":"Trauma airway guidance"},{"topic":"Neurology","question":"Thunderclap headache 14 hours earlier; normal noncontrast CT brain. Next step?","options":["CT definitively excludes SAH","Further investigation using LP or appropriate vascular imaging","Discharge without advice","Outpatient EEG"],"answer":1,"explanation":"CT sensitivity decreases with time; further testing is appropriate when suspicion for SAH remains.","pearl":"The six-hour CT rule does not apply at 14 hours.","reference":"AHA/ASA SAH guideline"},{"topic":"Neurology","question":"Disabling ischaemic stroke with large vessel occlusion and favourable imaging at 10 hours. What should be considered?","options":["No reperfusion after 6 hours","Endovascular thrombectomy if eligible","Routine heparin","Immediate carotid endarterectomy"],"answer":1,"explanation":"Selected patients benefit from thrombectomy beyond 6 hours according to tissue and vascular imaging.","pearl":"Time alone does not exclude thrombectomy.","reference":"AHA/ASA stroke guidance"},{"topic":"Neurology","question":"Generalised convulsions ongoing for 7 minutes with IV access. Preferred first-line medication class?","options":["Benzodiazepine","Phenytoin","Levetiracetam alone","Propofol without airway planning"],"answer":0,"explanation":"Treat convulsive status promptly with adequate-dose benzodiazepine and assess reversible causes.","pearl":"Five minutes of convulsions warrants status treatment.","reference":"Status epilepticus guidance"},{"topic":"Neurology","question":"Acute vertigo with profound truncal ataxia and inability to walk. Important diagnosis to exclude?","options":["BPPV","Posterior circulation stroke","Otitis externa","Vestibular migraine only"],"answer":1,"explanation":"Cerebellar stroke can present with severe gait instability; early CT is insensitive for posterior fossa infarction.","pearl":"Normal CT does not rule out posterior circulation stroke.","reference":"GRACE-3 dizziness guideline"},{"topic":"Neurology","question":"Warfarin-associated intracerebral haemorrhage with INR 3.8. Urgent reversal?","options":["Oral vitamin K alone","Four-factor PCC and IV vitamin K","Delayed FFP alone","Protamine"],"answer":1,"explanation":"Four-factor PCC rapidly replaces clotting factors; IV vitamin K sustains reversal.","pearl":"Reverse anticoagulation promptly in ICH.","reference":"AHA/ASA ICH guideline"},{"topic":"Infectious Diseases","question":"Suspected bacterial meningitis; LP delayed for CT. Priority?","options":["Wait for LP","Blood cultures then immediate empiric IV antibiotics without delay","Oral antibiotics","Observe"],"answer":1,"explanation":"Do not delay antibiotics for neuroimaging or LP; give dexamethasone when indicated.","pearl":"Time to antibiotics matters.","reference":"Bacterial meningitis guidance"},{"topic":"Infectious Diseases","question":"Rapidly progressive leg pain, fever, hypotension and skin discolouration with pain out of proportion. Key intervention?","options":["Urgent surgical debridement","Wait for MRI","Oral antibiotics and discharge","Topical antiseptic"],"answer":0,"explanation":"Necrotising infection needs immediate surgical source control with broad-spectrum antibiotics and resuscitation.","pearl":"Imaging must not delay surgery.","reference":"IDSA soft tissue infection guidance"},{"topic":"Infectious Diseases","question":"Chemotherapy patient with fever 39°C, ANC 0.2 and shock. Priority?","options":["Wait for cultures","Prompt antipseudomonal IV antibiotics and sepsis resuscitation","Oral amoxicillin alone","Wait for neutrophil recovery"],"answer":1,"explanation":"Neutropenic septic shock is time-critical; obtain cultures without delaying broad-spectrum treatment.","pearl":"Treat high-risk neutropenic fever immediately.","reference":"Febrile neutropenia guidance"},{"topic":"Infectious Diseases","question":"Haemodynamically stable suspected endocarditis. Preferred microbiology before antibiotics?","options":["Throat swab","Multiple blood culture sets from separate venepunctures","Urine culture alone","No cultures"],"answer":1,"explanation":"Multiple blood cultures improve organism identification; do not delay therapy if unstable.","pearl":"Culture before antibiotics when clinically safe.","reference":"ESC endocarditis guideline"},{"topic":"Infectious Diseases","question":"Shock with obstructed infected ureteric stone on CT. Essential intervention beyond antibiotics?","options":["Urgent urinary decompression","Outpatient lithotripsy","Steroids","Wait for spontaneous passage"],"answer":0,"explanation":"An infected obstructed collecting system requires urgent stent or nephrostomy for source control.","pearl":"Antibiotics alone cannot resolve obstructed sepsis.","reference":"EAU urolithiasis guidance"},{"topic":"Obstetrics & Gynaecology","question":"34-week pregnancy with severe hypertension and eclamptic seizure. Preferred drug to prevent recurrence?","options":["Phenytoin","Magnesium sulfate","Valproate","Diazepam maintenance"],"answer":1,"explanation":"Magnesium sulfate is first-line; stabilise airway, treat severe hypertension and involve obstetrics.","pearl":"Magnesium is preferred for eclampsia.","reference":"NICE pregnancy hypertension guidance"},{"topic":"Obstetrics & Gynaecology","question":"Positive pregnancy test, syncope, severe abdominal pain, BP 75/40 and free pelvic fluid. Priority?","options":["Serial beta-hCG","Urgent surgery for presumed ruptured ectopic pregnancy","Outpatient methotrexate","Discharge"],"answer":1,"explanation":"Resuscitate and arrange urgent gynaecological operative management for suspected haemorrhagic ectopic pregnancy.","pearl":"Do not delay definitive control in shock.","reference":"RCOG ectopic pregnancy guidance"},{"topic":"Obstetrics & Gynaecology","question":"Major postpartum haemorrhage from uterine atony. First-line uterotonic?","options":["Oxytocin","Methotrexate","Magnesium sulfate","Terbutaline"],"answer":0,"explanation":"Oxytocin is first-line alongside uterine massage, resuscitation, tranexamic acid when indicated and escalation.","pearl":"Resuscitation and haemorrhage control occur together.","reference":"WHO postpartum haemorrhage guidance"},{"topic":"Obstetrics & Gynaecology","question":"Sudden unilateral pelvic pain, enlarged ovary, but preserved Doppler flow. Best interpretation?","options":["Flow excludes torsion","Torsion remains possible; urgent gynaecology assessment","Proves PID","Discharge"],"answer":1,"explanation":"Dual ovarian blood supply and intermittent torsion mean Doppler flow cannot exclude torsion.","pearl":"Normal Doppler does not rule out torsion.","reference":"ACOG adnexal torsion guidance"},{"topic":"Obstetrics & Gynaecology","question":"At 30 weeks gestation, painless vaginal bleeding with soft non-tender uterus. What should be avoided until placenta praevia is excluded?","options":["Maternal resuscitation","Ultrasound","Digital vaginal examination","Fetal monitoring"],"answer":2,"explanation":"Digital vaginal examination may trigger severe haemorrhage in placenta praevia.","pearl":"Establish placental location first.","reference":"RCOG placenta praevia guidance"},{"topic":"Resuscitation","question":"A ventilated trauma patient becomes profoundly hypotensive with unilateral absent breath sounds. Immediate action?","options":["Increase PEEP","IV furosemide","CT chest","Needle or finger thoracostomy"],"answer":3,"explanation":"Treat tension pneumothorax immediately; do not delay decompression for imaging.","pearl":"Treat tension pneumothorax immediately; do not delay decompression for imaging.","reference":"ANZCOR ALS guidelines; local resuscitation protocols"},{"topic":"Resuscitation","question":"A patient with K 7.6 mmol/L has a sine-wave ECG. First medication?","options":["Sodium polystyrene","Nebulised salbutamol","IV calcium","IV furosemide"],"answer":2,"explanation":"IV calcium immediately stabilises the myocardium; potassium-shifting and removal therapies follow.","pearl":"IV calcium immediately stabilises the myocardium; potassium-shifting and removal therapies follow.","reference":"ANZCOR ALS guidelines; local resuscitation protocols"},{"topic":"Resuscitation","question":"After ROSC, a comatose patient has SpO2 100% on FiO2 1.0. Best oxygen strategy?","options":["Titrate oxygen to avoid hypoxaemia and hyperoxaemia","Stop oxygen immediately","Target SpO2 85%","Maintain FiO2 1.0 indefinitely"],"answer":0,"explanation":"Titrate oxygen using reliable saturation or blood gas measurement to avoid both extremes.","pearl":"Titrate oxygen using reliable saturation or blood gas measurement to avoid both extremes.","reference":"ANZCOR ALS guidelines; local resuscitation protocols"},{"topic":"Resuscitation","question":"A 70 kg adult has refractory anaphylactic shock despite repeated IM adrenaline. Next escalation?","options":["IV beta blocker","IV antihistamine alone","Titrated IV adrenaline infusion with expert monitoring","Oral prednisolone"],"answer":2,"explanation":"Refractory anaphylaxis warrants monitored IV adrenaline infusion and aggressive resuscitation.","pearl":"Refractory anaphylaxis warrants monitored IV adrenaline infusion and aggressive resuscitation.","reference":"ANZCOR ALS guidelines; local resuscitation protocols"},{"topic":"Resuscitation","question":"A septic patient has MAP 55 despite initial fluids and signs of overload. First vasopressor?","options":["Milrinone","Isoprenaline","Noradrenaline","Dopamine"],"answer":2,"explanation":"Noradrenaline is first-line for septic shock; avoid indiscriminate further fluids.","pearl":"Noradrenaline is first-line for septic shock; avoid indiscriminate further fluids.","reference":"ANZCOR ALS guidelines; local resuscitation protocols"},{"topic":"Resuscitation","question":"A 30-year-old has severe asthma, rising PaCO2 and drowsiness. What does rising CO2 imply?","options":["Impending ventilatory failure","Expected recovery","No significance","Anxiety-related hyperventilation"],"answer":0,"explanation":"Normalising or rising PaCO2 in severe asthma can signal exhaustion and impending respiratory failure.","pearl":"Normalising or rising PaCO2 in severe asthma can signal exhaustion and impending respiratory failure.","reference":"ANZCOR ALS guidelines; local resuscitation protocols"},{"topic":"Resuscitation","question":"A patient in PEA has ultrasound showing a large pericardial effusion and right-sided collapse. Targeted intervention?","options":["IV diuretic","Defibrillation","Adenosine","Urgent pericardial decompression"],"answer":3,"explanation":"Tamponade is a reversible obstructive cause of PEA; urgent drainage is required.","pearl":"Tamponade is a reversible obstructive cause of PEA; urgent drainage is required.","reference":"ANZCOR ALS guidelines; local resuscitation protocols"},{"topic":"Resuscitation","question":"A patient with shock and bradycardia remains unstable after atropine. Next action?","options":["Adenosine","Discharge","Transcutaneous pacing or vasoactive infusion","Oral beta blocker"],"answer":2,"explanation":"Persistent unstable bradycardia requires pacing and/or catecholamine support.","pearl":"Persistent unstable bradycardia requires pacing and/or catecholamine support.","reference":"ANZCOR ALS guidelines; local resuscitation protocols"},{"topic":"Resuscitation","question":"An unconscious diabetic has capillary glucose 1.4 mmol/L. Best immediate treatment with IV access?","options":["Oral glucose","IV dextrose","Glucagon only after CT","Subcutaneous insulin"],"answer":1,"explanation":"Severe symptomatic hypoglycaemia requires immediate parenteral glucose.","pearl":"Severe symptomatic hypoglycaemia requires immediate parenteral glucose.","reference":"ANZCOR ALS guidelines; local resuscitation protocols"},{"topic":"Resuscitation","question":"A shocked patient with severe metabolic acidosis has pH 7.04 and lactate 11. Most important initial priority?","options":["Restrict oxygen","Give bicarbonate to normalise pH in all cases","Identify and reverse the cause of shock","Delay source control"],"answer":2,"explanation":"Correction of hypoperfusion and the underlying cause is the priority; bicarbonate is selective.","pearl":"Correction of hypoperfusion and the underlying cause is the priority; bicarbonate is selective.","reference":"ANZCOR ALS guidelines; local resuscitation protocols"},{"topic":"Cardiology","question":"An irregular wide-complex tachycardia in a patient with WPW is haemodynamically stable. Which drug must be avoided?","options":["Procainamide","Expert-guided cardioversion","Verapamil","Ibutilide"],"answer":2,"explanation":"AV nodal blockers can accelerate accessory pathway conduction and cause VF.","pearl":"AV nodal blockers can accelerate accessory pathway conduction and cause VF.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A patient with chest pain has ST depression V1–V3 and tall R waves. Which leads help diagnose posterior STEMI?","options":["V7–V9","aVR only","V1 only","V3R–V4R"],"answer":0,"explanation":"Posterior leads V7–V9 can reveal posterior ST elevation.","pearl":"Posterior leads V7–V9 can reveal posterior ST elevation.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A patient with suspected acute aortic dissection is stable. Preferred diagnostic imaging?","options":["Coronary calcium score","Exercise ECG","Plain chest film alone","CT angiography of aorta"],"answer":3,"explanation":"CTA provides rapid anatomical confirmation of acute aortic syndromes.","pearl":"CTA provides rapid anatomical confirmation of acute aortic syndromes.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A stable regular narrow-complex tachycardia persists after vagal manoeuvres. Next drug?","options":["Atropine","Adenosine","Digoxin loading","Amiodarone first-line"],"answer":1,"explanation":"Adenosine is appropriate for regular AV-node-dependent SVT under monitoring.","pearl":"Adenosine is appropriate for regular AV-node-dependent SVT under monitoring.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A patient with acute pulmonary oedema and BP 210/120 remains distressed. Best initial strategy?","options":["Routine thrombolysis","Immediate oral beta blocker","Two litres crystalloid","NIV and titrated nitrates"],"answer":3,"explanation":"NIV and nitrates improve oxygenation and reduce afterload in hypertensive pulmonary oedema.","pearl":"NIV and nitrates improve oxygenation and reduce afterload in hypertensive pulmonary oedema.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A patient with syncope has a harsh systolic murmur radiating to carotids. Most concerning lesion?","options":["Mitral stenosis","Severe aortic stenosis","Pulmonary regurgitation","Tricuspid regurgitation"],"answer":1,"explanation":"Exertional syncope with an ejection murmur suggests haemodynamically significant aortic stenosis.","pearl":"Exertional syncope with an ejection murmur suggests haemodynamically significant aortic stenosis.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A patient has chest pain, diffuse ST elevation and PR depression. Most likely diagnosis?","options":["Hyperkalaemia","Digoxin effect","Acute pericarditis","Anterior STEMI"],"answer":2,"explanation":"Diffuse ST elevation and PR depression are typical of acute pericarditis.","pearl":"Diffuse ST elevation and PR depression are typical of acute pericarditis.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A patient with acute MI develops hypotension, new pansystolic murmur and pulmonary oedema. Suspect?","options":["Sinus bradycardia","Stable angina","Papillary muscle rupture","Pericarditis"],"answer":2,"explanation":"Acute severe mitral regurgitation after MI can result from papillary muscle rupture.","pearl":"Acute severe mitral regurgitation after MI can result from papillary muscle rupture.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A patient with AF and ventricular rate 180 is shocked and confused. Immediate treatment?","options":["Oral metoprolol only","Aspirin","Routine observation","Synchronized electrical cardioversion"],"answer":3,"explanation":"Haemodynamic instability due to AF mandates urgent synchronized cardioversion.","pearl":"Haemodynamic instability due to AF mandates urgent synchronized cardioversion.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A patient with tamponade has hypotension and right ventricular diastolic collapse. Definitive intervention?","options":["Oral beta blocker","Urgent pericardial drainage","Exercise testing","High-dose furosemide"],"answer":1,"explanation":"Tamponade with haemodynamic compromise requires prompt drainage.","pearl":"Tamponade with haemodynamic compromise requires prompt drainage.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Respiratory","question":"A patient with COPD exacerbation has pH 7.27 and PaCO2 74 mmHg despite medical treatment. Best ventilatory support?","options":["Routine CPAP without pressure support","Non-invasive ventilation","No ventilatory support","High-flow oxygen alone indefinitely"],"answer":1,"explanation":"NIV reduces intubation and mortality in selected acidotic COPD exacerbations.","pearl":"NIV reduces intubation and mortality in selected acidotic COPD exacerbations.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"A patient with acute pleuritic pain, tachycardia and hypoxaemia has high clinical probability of PE. Next imaging if stable?","options":["CT pulmonary angiography","Chest radiograph alone","Spirometry","D-dimer to exclude PE"],"answer":0,"explanation":"High-probability suspected PE generally requires definitive imaging rather than D-dimer exclusion.","pearl":"High-probability suspected PE generally requires definitive imaging rather than D-dimer exclusion.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"A patient with severe asthma has a silent chest and exhaustion. Interpretation?","options":["Clinical improvement","Mild asthma","Pure anxiety","Life-threatening airflow obstruction"],"answer":3,"explanation":"Silent chest and exhaustion indicate critical obstruction and impending respiratory failure.","pearl":"Silent chest and exhaustion indicate critical obstruction and impending respiratory failure.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"A patient with pneumonia develops a large loculated pleural collection with pH 7.05. Management?","options":["Routine bronchodilator","Antibiotics and pleural drainage","Oral antibiotics alone","Observation"],"answer":1,"explanation":"Complicated parapneumonic effusions with low pH usually require drainage.","pearl":"Complicated parapneumonic effusions with low pH usually require drainage.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"A patient with haemoptysis becomes hypoxic and hypotensive. Immediate priority?","options":["CT before resuscitation","Discharge","Airway protection and positioning to protect unaffected lung","Oral antibiotics only"],"answer":2,"explanation":"Massive haemoptysis kills by asphyxiation; airway management takes priority.","pearl":"Massive haemoptysis kills by asphyxiation; airway management takes priority.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"A patient with sudden unilateral pleuritic pain has a small primary spontaneous pneumothorax and no breathlessness. Appropriate strategy?","options":["Routine thrombolysis","Conservative observation with follow-up when eligible","Mandatory thoracotomy","High-dose steroids"],"answer":1,"explanation":"Selected stable primary spontaneous pneumothoraces can be managed conservatively.","pearl":"Selected stable primary spontaneous pneumothoraces can be managed conservatively.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"A patient has diffuse bilateral infiltrates, severe hypoxaemia and no evidence of cardiogenic oedema. Syndrome?","options":["Asthma alone","ARDS","Pneumothorax","Isolated PE"],"answer":1,"explanation":"ARDS is acute non-cardiogenic respiratory failure with bilateral opacities and hypoxaemia.","pearl":"ARDS is acute non-cardiogenic respiratory failure with bilateral opacities and hypoxaemia.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"An obese patient with OSA receives opioids and develops hypoventilation. Immediate priority?","options":["Support ventilation and reverse opioid effect if indicated","Routine diuretics","More opioids","Discharge"],"answer":0,"explanation":"Treat hypoventilation promptly; naloxone may be required when opioids contribute.","pearl":"Treat hypoventilation promptly; naloxone may be required when opioids contribute.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"A patient has acute stridor after extubation. Most concerning mechanism?","options":["Upper airway oedema","Pulmonary embolism","Pleural effusion","Lower lobe pneumonia"],"answer":0,"explanation":"Post-extubation stridor indicates potential upper airway narrowing requiring urgent assessment.","pearl":"Post-extubation stridor indicates potential upper airway narrowing requiring urgent assessment.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"A patient with severe pneumonia and shock has lactate 5.4. Which management is time critical?","options":["Prompt IV antibiotics and haemodynamic resuscitation","Wait for sputum culture","Outpatient review","Oral cough syrup"],"answer":0,"explanation":"Severe pneumonia with shock requires immediate sepsis treatment.","pearl":"Severe pneumonia with shock requires immediate sepsis treatment.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Toxicology","question":"A patient with TCA overdose has QRS 160 ms and hypotension. Targeted treatment?","options":["IV calcium only","Flumazenil","Phenytoin","IV sodium bicarbonate"],"answer":3,"explanation":"Sodium bicarbonate treats TCA-related sodium-channel blockade.","pearl":"Sodium bicarbonate treats TCA-related sodium-channel blockade.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient has salicylate poisoning with tinnitus, acidosis and tachypnoea. Elimination strategy?","options":["Urine acidification","Urinary alkalinisation with bicarbonate","Forced diuresis alone","Flumazenil"],"answer":1,"explanation":"Urinary alkalinisation enhances salicylate excretion; severe toxicity may require dialysis.","pearl":"Urinary alkalinisation enhances salicylate excretion; severe toxicity may require dialysis.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient with suspected opioid overdose is apnoeic with pinpoint pupils. Priority?","options":["CT before airway support","Flumazenil","Ventilation and titrated naloxone","Activated charcoal by mouth"],"answer":2,"explanation":"Ventilation is immediately lifesaving; naloxone restores respiratory drive.","pearl":"Ventilation is immediately lifesaving; naloxone restores respiratory drive.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient with methanol ingestion has visual symptoms and high-anion-gap acidosis. Antidote?","options":["Pralidoxime","N-acetylcysteine","Atropine","Fomepizole"],"answer":3,"explanation":"Fomepizole blocks alcohol dehydrogenase; dialysis may be needed.","pearl":"Fomepizole blocks alcohol dehydrogenase; dialysis may be needed.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient with organophosphate exposure has bronchorrhoea, bradycardia and miosis. Antidote?","options":["Naloxone","Atropine","Glucagon","N-acetylcysteine"],"answer":1,"explanation":"Atropine reverses muscarinic toxicity; oximes may also be indicated.","pearl":"Atropine reverses muscarinic toxicity; oximes may also be indicated.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient with severe calcium-channel blocker overdose remains shocked despite fluids. Adjunct?","options":["High-dose insulin euglycaemic therapy","Beta blocker","Adenosine","Verapamil"],"answer":0,"explanation":"High-dose insulin can improve myocardial function in severe CCB poisoning.","pearl":"High-dose insulin can improve myocardial function in severe CCB poisoning.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient with lithium toxicity has severe ataxia, confusion and renal impairment. Enhanced elimination?","options":["Urinary acidification","Naloxone","Activated charcoal","Haemodialysis"],"answer":3,"explanation":"Severe lithium toxicity with neurological signs warrants urgent dialysis consideration.","pearl":"Severe lithium toxicity with neurological signs warrants urgent dialysis consideration.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient develops seizures and arrhythmias after local anaesthetic injection. Specific treatment?","options":["Fomepizole","IV lipid emulsion","N-acetylcysteine","Pralidoxime"],"answer":1,"explanation":"Lipid emulsion is used for severe local anaesthetic systemic toxicity.","pearl":"Lipid emulsion is used for severe local anaesthetic systemic toxicity.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient on serotonergic agents has clonus, hyperreflexia and hyperthermia. Diagnosis?","options":["Opioid toxicity","Serotonin toxicity","Anticholinergic toxicity","Neuroleptic malignant syndrome"],"answer":1,"explanation":"Clonus and hyperreflexia strongly suggest serotonin toxicity.","pearl":"Clonus and hyperreflexia strongly suggest serotonin toxicity.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient with severe iron poisoning has shock and metabolic acidosis. Chelator?","options":["Penicillamine","Fomepizole","Deferoxamine","Dimercaprol"],"answer":2,"explanation":"Deferoxamine is the specific chelator for severe iron poisoning.","pearl":"Deferoxamine is the specific chelator for severe iron poisoning.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Paediatrics","question":"A child with croup has stridor at rest and marked recession. Treatment?","options":["Dexamethasone and nebulised adrenaline","Antihistamine only","Routine antibiotics","Salbutamol only"],"answer":0,"explanation":"Corticosteroids and nebulised adrenaline are indicated in severe croup.","pearl":"Corticosteroids and nebulised adrenaline are indicated in severe croup.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"An infant has bilious vomiting and abdominal distension. Critical diagnosis to exclude?","options":["Pyloric stenosis","Gastro-oesophageal reflux","Colic","Malrotation with volvulus"],"answer":3,"explanation":"Bilious vomiting in infancy warrants urgent surgical assessment for volvulus.","pearl":"Bilious vomiting in infancy warrants urgent surgical assessment for volvulus.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"A toddler has intermittent severe abdominal pain and red currant jelly stool. Likely diagnosis?","options":["Meckel diverticulitis","Intussusception","Gastroenteritis only","Pyloric stenosis"],"answer":1,"explanation":"Intussusception causes episodic pain and sometimes bloody mucus stool.","pearl":"Intussusception causes episodic pain and sometimes bloody mucus stool.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"A febrile child has petechiae, prolonged capillary refill and hypotension. Priority?","options":["Immediate antibiotics and shock resuscitation","Wait for lumbar puncture","Discharge","Oral antihistamine"],"answer":0,"explanation":"Suspected meningococcal sepsis requires immediate treatment.","pearl":"Suspected meningococcal sepsis requires immediate treatment.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"A child with DKA develops headache, bradycardia and reduced GCS during treatment. Suspect?","options":["Clinical recovery","Migraine","Hypocalcaemia only","Cerebral injury"],"answer":3,"explanation":"DKA-related cerebral injury needs immediate treatment and senior escalation.","pearl":"DKA-related cerebral injury needs immediate treatment and senior escalation.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"A 7-week-old has projectile non-bilious vomiting and hypochloraemic alkalosis. Diagnosis?","options":["Hirschsprung disease","Intussusception","Malrotation with volvulus","Pyloric stenosis"],"answer":3,"explanation":"Pyloric stenosis produces progressive projectile non-bilious vomiting and metabolic alkalosis.","pearl":"Pyloric stenosis produces progressive projectile non-bilious vomiting and metabolic alkalosis.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"A child with fever, painful hip rotation and refusal to weight-bear needs exclusion of?","options":["Migraine","Septic arthritis","Bursitis","Growing pains"],"answer":1,"explanation":"Septic arthritis can rapidly damage cartilage and requires urgent assessment.","pearl":"Septic arthritis can rapidly damage cartilage and requires urgent assessment.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"An infant with SVT has poor perfusion and hypotension. Immediate treatment?","options":["Observation","Synchronized cardioversion","Carotid massage","Oral digoxin"],"answer":1,"explanation":"Unstable paediatric SVT warrants synchronized electrical cardioversion.","pearl":"Unstable paediatric SVT warrants synchronized electrical cardioversion.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"A child with bronchiolitis has SpO2 87% and increased work of breathing. Best initial care?","options":["Routine antibiotics","Routine salbutamol","Oxygen and supportive management","Routine steroids"],"answer":2,"explanation":"Bronchiolitis management is supportive; oxygen is appropriate for significant hypoxaemia.","pearl":"Bronchiolitis management is supportive; oxygen is appropriate for significant hypoxaemia.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"A child has a brief generalised febrile seizure, full recovery and normal examination. Next?","options":["Chronic antiepileptic therapy","Routine LP for all","Routine CT brain","Reassurance and assess fever source"],"answer":3,"explanation":"Simple febrile seizures generally do not require routine imaging or anticonvulsants.","pearl":"Simple febrile seizures generally do not require routine imaging or anticonvulsants.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Trauma","question":"An unstable blunt trauma patient has free intraperitoneal fluid on FAST. Next?","options":["Urgent operative haemorrhage control","Observation","CT before any intervention","Oral tranexamic acid"],"answer":0,"explanation":"Unstable trauma with positive FAST needs immediate source control.","pearl":"Unstable trauma with positive FAST needs immediate source control.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A pelvic fracture patient is shocked. Where should the pelvic binder sit?","options":["Over iliac crests","Around knees","Over greater trochanters","Across abdomen"],"answer":2,"explanation":"Binders reduce pelvic volume most effectively over the greater trochanters.","pearl":"Binders reduce pelvic volume most effectively over the greater trochanters.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A penetrating chest injury patient is shocked with pericardial fluid on ultrasound. Priority?","options":["Outpatient echo","Beta blockade","Urgent surgical management of tamponade","Diuresis"],"answer":2,"explanation":"Penetrating traumatic tamponade requires urgent surgical source control.","pearl":"Penetrating traumatic tamponade requires urgent surgical source control.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A patient with severe TBI has GCS 6 and is hypoxic. First priority?","options":["Delay until CT","Give oral analgesia","Secure airway while preventing hypotension","Observe without monitoring"],"answer":2,"explanation":"Preventing secondary brain injury from hypoxia and hypotension is essential.","pearl":"Preventing secondary brain injury from hypoxia and hypotension is essential.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A patient with an open tibial fracture has soil contamination. Early management?","options":["Repeated manipulation","Delay antibiotics","Immediate ED closure","IV antibiotics, sterile dressing and surgical referral"],"answer":3,"explanation":"Early antibiotics and operative debridement are central to open-fracture care.","pearl":"Early antibiotics and operative debridement are central to open-fracture care.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A patient with a flail chest is hypoxaemic and splinting due to pain. Management?","options":["Effective analgesia and respiratory support","Fluid restriction only","Chest strapping","Routine corticosteroids"],"answer":0,"explanation":"Analgesia and respiratory support improve ventilation and prevent complications.","pearl":"Analgesia and respiratory support improve ventilation and prevent complications.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A burn patient from an enclosed-space fire develops hoarseness and facial burns. Priority?","options":["Nebulised salbutamol only","Discharge if SpO2 normal","Early expert airway assessment","Wait for stridor"],"answer":2,"explanation":"Airway oedema may progress rapidly after inhalation injury.","pearl":"Airway oedema may progress rapidly after inhalation injury.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A patient with crush injury has K 7.3 and peaked T waves. First cardiac treatment?","options":["Wait for CK","Oral potassium","Diuretic alone","IV calcium"],"answer":3,"explanation":"Hyperkalaemic ECG changes warrant immediate IV calcium.","pearl":"Hyperkalaemic ECG changes warrant immediate IV calcium.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A patient has a rapidly expanding neck haematoma and stridor after blunt injury. Priority?","options":["CT first regardless of stability","Neck traction","Controlled airway management by experienced team","Discharge"],"answer":2,"explanation":"Expanding neck haematoma threatens airway patency.","pearl":"Expanding neck haematoma threatens airway patency.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A patient has compartment pain out of proportion and pain on passive stretch after tibial fracture. Next?","options":["Wait for absent pulses","Routine outpatient review","Urgent surgical assessment for fasciotomy","Apply tight cast"],"answer":2,"explanation":"Acute compartment syndrome is a surgical emergency; pulses may remain present.","pearl":"Acute compartment syndrome is a surgical emergency; pulses may remain present.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Neurology","question":"A patient with thunderclap headache has a normal CT 16 hours after onset. Next if SAH concern persists?","options":["EEG","LP or appropriate vascular investigation","Routine MRI in a month","Discharge unconditionally"],"answer":1,"explanation":"A delayed negative CT does not reliably exclude SAH in all patients.","pearl":"A delayed negative CT does not reliably exclude SAH in all patients.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient has convulsed continuously for 8 minutes. First-line drug class?","options":["Phenytoin first","Propofol without airway plan","Valproate only","Benzodiazepine"],"answer":3,"explanation":"Status epilepticus needs immediate adequate-dose benzodiazepine therapy.","pearl":"Status epilepticus needs immediate adequate-dose benzodiazepine therapy.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient with acute vestibular syndrome cannot stand and has severe truncal ataxia. Exclude?","options":["Anxiety","Otitis externa","Posterior circulation stroke","Simple BPPV"],"answer":2,"explanation":"Severe truncal ataxia is a central neurological red flag.","pearl":"Severe truncal ataxia is a central neurological red flag.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient with warfarin-related intracerebral haemorrhage has INR 4.0. Urgent reversal?","options":["No reversal","Four-factor PCC plus IV vitamin K","Oral vitamin K only","Protamine"],"answer":1,"explanation":"PCC rapidly reverses warfarin while IV vitamin K sustains correction.","pearl":"PCC rapidly reverses warfarin while IV vitamin K sustains correction.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient with ascending weakness, areflexia and declining vital capacity has likely?","options":["Multiple sclerosis relapse","Bell palsy","Stroke","Guillain–Barré syndrome"],"answer":3,"explanation":"GBS may cause respiratory failure; serial respiratory measurements are essential.","pearl":"GBS may cause respiratory failure; serial respiratory measurements are essential.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient has fluctuating ptosis, bulbar weakness and respiratory distress. Concern?","options":["Myasthenic crisis","BPPV","Migraine","Peripheral neuropathy only"],"answer":0,"explanation":"Myasthenic crisis requires close respiratory assessment and critical care support.","pearl":"Myasthenic crisis requires close respiratory assessment and critical care support.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient has fever, altered behaviour and focal seizures. Empiric antiviral?","options":["Metronidazole","Fluconazole","Oseltamivir","IV aciclovir"],"answer":3,"explanation":"Treat suspected HSV encephalitis promptly with IV aciclovir.","pearl":"Treat suspected HSV encephalitis promptly with IV aciclovir.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient has back pain, saddle anaesthesia and urinary retention. Investigation?","options":["Routine lumbar X-ray","No imaging","Urgent MRI spine","Outpatient nerve conduction study"],"answer":2,"explanation":"Cauda equina syndrome requires urgent MRI and spinal assessment.","pearl":"Cauda equina syndrome requires urgent MRI and spinal assessment.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient has disabling ischaemic stroke at 9 hours with favourable perfusion imaging and LVO. Consider?","options":["Routine heparin","Mechanical thrombectomy","Immediate carotid endarterectomy","No reperfusion after 6 hours"],"answer":1,"explanation":"Selected large-vessel strokes benefit from thrombectomy in extended windows.","pearl":"Selected large-vessel strokes benefit from thrombectomy in extended windows.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient with severe headache, papilloedema and focal deficits needs LP. First step?","options":["EEG only","Discharge","Neuroimaging and assess LP safety","Immediate LP without assessment"],"answer":2,"explanation":"Focal deficits and signs of raised intracranial pressure require assessment before LP.","pearl":"Focal deficits and signs of raised intracranial pressure require assessment before LP.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Infectious Diseases","question":"A patient has fever, neck stiffness and confusion; CT will delay LP. Best next?","options":["Wait for LP","Observation","Blood cultures then prompt IV antibiotics","Oral antibiotics"],"answer":2,"explanation":"Antibiotics should not be delayed for imaging or lumbar puncture.","pearl":"Antibiotics should not be delayed for imaging or lumbar puncture.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"A patient with severe leg pain, bullae and shock may have necrotising fasciitis. Priority?","options":["Topical therapy","Urgent surgical exploration","Oral antibiotics alone","Wait for MRI"],"answer":1,"explanation":"Early surgical debridement is crucial in necrotising soft-tissue infection.","pearl":"Early surgical debridement is crucial in necrotising soft-tissue infection.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"A chemotherapy patient has ANC 0.1 and septic shock. Priority?","options":["Observe","Wait for cultures","Prompt antipseudomonal IV antibiotics","Oral amoxicillin"],"answer":2,"explanation":"Neutropenic sepsis requires immediate broad-spectrum IV antibiotics.","pearl":"Neutropenic sepsis requires immediate broad-spectrum IV antibiotics.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"A patient with an infected obstructing ureteric stone is in shock. Essential treatment?","options":["Observation","Outpatient lithotripsy","Steroids","Urgent urinary drainage"],"answer":3,"explanation":"Infected obstruction requires immediate source control by stent or nephrostomy.","pearl":"Infected obstruction requires immediate source control by stent or nephrostomy.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"An IV drug user has fever, back pain and new leg weakness. Urgent test?","options":["D-dimer","Outpatient EMG","Plain radiograph alone","MRI spine"],"answer":3,"explanation":"Spinal epidural abscess can rapidly cause irreversible neurological injury.","pearl":"Spinal epidural abscess can rapidly cause irreversible neurological injury.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"A diabetic has severe otalgia, ear canal granulation and cranial neuropathy. Suspect?","options":["Simple otitis media","BPPV","Viral URTI","Necrotising otitis externa"],"answer":3,"explanation":"Skull-base infection requires urgent specialist treatment.","pearl":"Skull-base infection requires urgent specialist treatment.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"A patient with recent antibiotics has diarrhoea, shock and toxic megacolon. Likely pathogen?","options":["Clostridioides difficile","Giardia","Influenza","Norovirus only"],"answer":0,"explanation":"Fulminant C difficile infection can cause ileus and megacolon.","pearl":"Fulminant C difficile infection can cause ileus and megacolon.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"A returning traveller from sub-Saharan Africa has fever and confusion. Urgent exclusion?","options":["Migraine","Falciparum malaria","BPPV","Seasonal allergy"],"answer":1,"explanation":"Severe malaria is a time-critical diagnosis in febrile returning travellers.","pearl":"Severe malaria is a time-critical diagnosis in febrile returning travellers.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"A patient with HIV CD4 35 has meningitis and elevated opening pressure. Key test?","options":["Rapid strep test","Monospot","Urine dipstick","CSF cryptococcal antigen"],"answer":3,"explanation":"CSF cryptococcal antigen supports diagnosis; raised pressure requires management.","pearl":"CSF cryptococcal antigen supports diagnosis; raised pressure requires management.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"A stable patient with suspected endocarditis needs antibiotics. What microbiology first?","options":["Urine culture only","Multiple blood culture sets","Throat swab only","No cultures"],"answer":1,"explanation":"Obtain multiple blood cultures before antibiotics when clinically safe.","pearl":"Obtain multiple blood cultures before antibiotics when clinically safe.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Obstetrics & Gynaecology","question":"A pregnant patient has a seizure and severe hypertension. First-line anticonvulsant?","options":["Levetiracetam alone","Magnesium sulfate","Phenytoin","Valproate"],"answer":1,"explanation":"Magnesium sulfate is first-line to treat and prevent eclamptic seizures.","pearl":"Magnesium sulfate is first-line to treat and prevent eclamptic seizures.","reference":"RANZCOG guidance; local maternity protocols"},{"topic":"Obstetrics & Gynaecology","question":"A patient has a positive pregnancy test, shock and free intraperitoneal fluid. Priority?","options":["Outpatient methotrexate","Discharge","Urgent surgery for suspected ruptured ectopic","Serial hCG only"],"answer":2,"explanation":"Ruptured ectopic pregnancy with shock requires operative management.","pearl":"Ruptured ectopic pregnancy with shock requires operative management.","reference":"RANZCOG guidance; local maternity protocols"},{"topic":"Obstetrics & Gynaecology","question":"A patient has atonic postpartum haemorrhage. First-line uterotonic?","options":["Terbutaline","Oxytocin","Methotrexate","Magnesium sulfate"],"answer":1,"explanation":"Oxytocin is first-line for uterine atony alongside haemorrhage resuscitation.","pearl":"Oxytocin is first-line for uterine atony alongside haemorrhage resuscitation.","reference":"RANZCOG guidance; local maternity protocols"},{"topic":"Obstetrics & Gynaecology","question":"A patient has ovarian torsion symptoms but Doppler flow is preserved. Interpretation?","options":["Torsion is not excluded","Confirms PID","Torsion is excluded","No follow-up needed"],"answer":0,"explanation":"Preserved Doppler flow cannot reliably exclude ovarian torsion.","pearl":"Preserved Doppler flow cannot reliably exclude ovarian torsion.","reference":"RANZCOG guidance; local maternity protocols"},{"topic":"Obstetrics & Gynaecology","question":"A third-trimester patient has painless bleeding and unknown placental position. Avoid?","options":["Fetal monitoring","Digital vaginal examination","Maternal resuscitation","Ultrasound"],"answer":1,"explanation":"Digital examination may precipitate major bleeding with placenta praevia.","pearl":"Digital examination may precipitate major bleeding with placenta praevia.","reference":"RANZCOG guidance; local maternity protocols"},{"topic":"Obstetrics & Gynaecology","question":"A patient at 33 weeks has BP 185/115, headache and visual changes. Immediate action?","options":["Wait for labour","ACE inhibitor","Treat severe hypertension and assess pre-eclampsia","Discharge"],"answer":2,"explanation":"Severe hypertension in pregnancy requires urgent management and obstetric input.","pearl":"Severe hypertension in pregnancy requires urgent management and obstetric input.","reference":"RANZCOG guidance; local maternity protocols"},{"topic":"Obstetrics & Gynaecology","question":"A postpartum patient bleeds heavily despite a firm uterus. Important cause?","options":["Normal lochia","Uterine atony only","Hyperemesis","Genital tract trauma"],"answer":3,"explanation":"Bleeding with a firm uterus suggests lacerations or retained tissue.","pearl":"Bleeding with a firm uterus suggests lacerations or retained tissue.","reference":"RANZCOG guidance; local maternity protocols"},{"topic":"Obstetrics & Gynaecology","question":"A pregnant patient has painful vaginal bleeding and a tender rigid uterus. Suspect?","options":["Normal labour","Placenta praevia only","Placental abruption","Cervicitis"],"answer":2,"explanation":"Painful bleeding and uterine tenderness support abruption.","pearl":"Painful bleeding and uterine tenderness support abruption.","reference":"RANZCOG guidance; local maternity protocols"},{"topic":"Obstetrics & Gynaecology","question":"A patient with pelvic pain, fever and cervical motion tenderness needs?","options":["Steroids alone","Antifungal alone","Empiric antibiotics for PID","Wait for STI results"],"answer":2,"explanation":"Early empirical PID treatment reduces reproductive complications.","pearl":"Early empirical PID treatment reduces reproductive complications.","reference":"RANZCOG guidance; local maternity protocols"},{"topic":"Obstetrics & Gynaecology","question":"A postpartum patient has a severe headache and focal neurological deficits. Priority?","options":["Caffeine alone","Discharge","Urgent evaluation for cerebral venous thrombosis and other causes","Assume benign PDPH"],"answer":2,"explanation":"Postpartum focal neurological deficits are red flags for intracranial pathology.","pearl":"Postpartum focal neurological deficits are red flags for intracranial pathology.","reference":"RANZCOG guidance; local maternity protocols"},{"topic":"Gastroenterology","question":"A patient has haematemesis, shock and suspected variceal bleeding. Initial targeted treatment?","options":["Discharge","Vasoactive therapy and IV antibiotics with resuscitation","Routine thrombolysis","Oral PPI alone"],"answer":1,"explanation":"Suspected variceal bleeding requires resuscitation, vasoactive treatment, antibiotics and urgent endoscopy.","pearl":"Suspected variceal bleeding requires resuscitation, vasoactive treatment, antibiotics and urgent endoscopy.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient has severe epigastric pain, lipase four times normal and gallstones. Initial priority?","options":["Routine prophylactic antibiotics","Supportive resuscitation and assess biliary obstruction","Immediate ERCP for all","Discharge"],"answer":1,"explanation":"Acute pancreatitis requires supportive care; ERCP is reserved for obstruction or cholangitis.","pearl":"Acute pancreatitis requires supportive care; ERCP is reserved for obstruction or cholangitis.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient with cirrhosis has ascites, fever and abdominal pain. Diagnostic test?","options":["Urgent diagnostic paracentesis","Colonoscopy","HIDA scan","Breath test"],"answer":0,"explanation":"Ascitic fluid cell count and culture diagnose spontaneous bacterial peritonitis.","pearl":"Ascitic fluid cell count and culture diagnose spontaneous bacterial peritonitis.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient with GI bleeding has haemodynamic instability despite resuscitation. Priority?","options":["Urgent definitive haemorrhage control","Oral iron only","Observation","Outpatient endoscopy"],"answer":0,"explanation":"Ongoing unstable GI bleeding requires urgent endoscopic or interventional source control.","pearl":"Ongoing unstable GI bleeding requires urgent endoscopic or interventional source control.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient has severe abdominal pain out of proportion to examination and AF. Concern?","options":["Acute mesenteric ischaemia","Viral gastroenteritis","Simple constipation","Irritable bowel syndrome"],"answer":0,"explanation":"Mesenteric ischaemia presents with severe pain and may have initially subtle signs.","pearl":"Mesenteric ischaemia presents with severe pain and may have initially subtle signs.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient has cholangitis with shock, jaundice and biliary obstruction. Source control?","options":["Elective colonoscopy","Observation","Urgent ERCP biliary drainage","Steroids"],"answer":2,"explanation":"Severe cholangitis requires antibiotics, resuscitation and urgent biliary drainage.","pearl":"Severe cholangitis requires antibiotics, resuscitation and urgent biliary drainage.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient has peritonitis and free air under diaphragm. Priority?","options":["Routine ultrasound in a week","Urgent surgical evaluation","Discharge","Oral laxatives"],"answer":1,"explanation":"Perforated viscus with peritonitis requires urgent surgical management.","pearl":"Perforated viscus with peritonitis requires urgent surgical management.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient with ulcerative colitis has fever, distension and colonic diameter 8 cm. Suspect?","options":["Renal colic","Appendicitis","Simple constipation","Toxic megacolon"],"answer":3,"explanation":"Systemic toxicity with colonic dilation suggests toxic megacolon and warrants urgent specialist care.","pearl":"Systemic toxicity with colonic dilation suggests toxic megacolon and warrants urgent specialist care.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient with severe upper GI bleed is taking warfarin and has INR 5.5. Key consideration?","options":["Give aspirin","Urgent anticoagulant reversal in life-threatening bleeding","Continue warfarin","Delay haemostasis"],"answer":1,"explanation":"Life-threatening bleeding requires reversal and source control.","pearl":"Life-threatening bleeding requires reversal and source control.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient has severe pancreatitis with hypotension and organ failure. Disposition?","options":["Oral antibiotics only","Immediate discharge","Routine outpatient MRI","Critical care assessment"],"answer":3,"explanation":"Persistent organ failure defines severe pancreatitis and requires intensive support.","pearl":"Persistent organ failure defines severe pancreatitis and requires intensive support.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Renal & Metabolic","question":"A patient with DKA has K 2.9 mmol/L before insulin. First step?","options":["Start insulin immediately at high dose","Give bicarbonate only","Replace potassium before insulin","Discharge"],"answer":2,"explanation":"Insulin worsens hypokalaemia; potassium should be corrected before insulin when markedly low.","pearl":"Insulin worsens hypokalaemia; potassium should be corrected before insulin when markedly low.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient with severe symptomatic hyponatraemia is actively seizing. Treatment?","options":["Oral salt only","Dextrose 5%","Free water","Hypertonic saline bolus"],"answer":3,"explanation":"Seizures from hyponatraemia require controlled hypertonic saline boluses and monitoring.","pearl":"Seizures from hyponatraemia require controlled hypertonic saline boluses and monitoring.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient has hypercalcaemia 4.1 mmol/L with confusion and dehydration. Initial treatment?","options":["Fluid restriction","IV isotonic saline with careful reassessment","Calcium supplements","Thiazide diuretic"],"answer":1,"explanation":"Severe symptomatic hypercalcaemia requires hydration and targeted calcium-lowering therapy.","pearl":"Severe symptomatic hypercalcaemia requires hydration and targeted calcium-lowering therapy.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient has adrenal crisis with shock, hyponatraemia and hyperkalaemia. Immediate treatment?","options":["IV hydrocortisone and isotonic fluid","Wait for cortisol result","Insulin alone","Oral prednisolone next week"],"answer":0,"explanation":"Suspected adrenal crisis is treated immediately with parenteral hydrocortisone and resuscitation.","pearl":"Suspected adrenal crisis is treated immediately with parenteral hydrocortisone and resuscitation.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient with uraemia has pericarditis and refractory hyperkalaemia. Definitive treatment?","options":["Oral diuretics only","Urgent dialysis","Routine antibiotics","Observation"],"answer":1,"explanation":"Uraemic pericarditis and refractory hyperkalaemia are indications for urgent renal replacement therapy.","pearl":"Uraemic pericarditis and refractory hyperkalaemia are indications for urgent renal replacement therapy.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient has thyroid storm with fever, tachyarrhythmia and altered consciousness. Initial management?","options":["Insulin only","Levothyroxine","Multimodal thyroid storm therapy and supportive care","Observation"],"answer":2,"explanation":"Treat with supportive care, beta blockade if safe, antithyroid therapy and glucocorticoids.","pearl":"Treat with supportive care, beta blockade if safe, antithyroid therapy and glucocorticoids.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient has myxoedema coma with hypothermia and bradycardia. Treatment?","options":["Antithyroid medication","Discharge","IV thyroid hormone and stress-dose hydrocortisone","Insulin only"],"answer":2,"explanation":"Myxoedema coma is life-threatening and requires hormone replacement and supportive care.","pearl":"Myxoedema coma is life-threatening and requires hormone replacement and supportive care.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient with HHS has glucose 52 mmol/L and profound dehydration. Initial priority?","options":["Fluid restriction","Immediate high-dose insulin before fluids","Careful fluid resuscitation and electrolyte assessment","Oral hypoglycaemic only"],"answer":2,"explanation":"HHS treatment begins with fluids and electrolyte management; insulin is introduced carefully.","pearl":"HHS treatment begins with fluids and electrolyte management; insulin is introduced carefully.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient with severe rhabdomyolysis has rising creatinine and dark urine. Main early intervention?","options":["NSAIDs","Isotonic IV fluids with monitoring","Fluid restriction","Routine urine acidification for all"],"answer":1,"explanation":"Early fluids and electrolyte monitoring are key to preventing renal complications.","pearl":"Early fluids and electrolyte monitoring are key to preventing renal complications.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient with profound hypophosphataemia develops respiratory weakness. Treatment?","options":["Restrict phosphate","Calcium only","Routine diuretics","Carefully monitored phosphate replacement"],"answer":3,"explanation":"Severe symptomatic hypophosphataemia warrants replacement with monitoring for complications.","pearl":"Severe symptomatic hypophosphataemia warrants replacement with monitoring for complications.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient has painful red eye, halos, mid-dilated pupil and high IOP. Diagnosis?","options":["Conjunctivitis","Acute angle-closure glaucoma","Blepharitis","Retinal detachment"],"answer":1,"explanation":"Angle closure is an ophthalmic emergency requiring urgent pressure-lowering therapy.","pearl":"Angle closure is an ophthalmic emergency requiring urgent pressure-lowering therapy.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient has sudden painless monocular vision loss and a cherry-red macula. Diagnosis?","options":["Optic neuritis","Conjunctivitis","Central retinal artery occlusion","Corneal abrasion"],"answer":2,"explanation":"CRAO is an ocular stroke requiring urgent stroke-pathway evaluation.","pearl":"CRAO is an ocular stroke requiring urgent stroke-pathway evaluation.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient with contact lens use has a painful red eye and corneal infiltrate. Concern?","options":["Dry eye only","Simple allergic conjunctivitis","Migraine","Microbial keratitis"],"answer":3,"explanation":"Contact lens-associated keratitis can threaten vision and needs urgent ophthalmology input.","pearl":"Contact lens-associated keratitis can threaten vision and needs urgent ophthalmology input.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient has proptosis, fever and painful restricted eye movements. Diagnosis?","options":["BPPV","Preseptal cellulitis only","Orbital cellulitis","Conjunctivitis"],"answer":2,"explanation":"Orbital signs suggest post-septal infection and require urgent imaging and IV antibiotics.","pearl":"Orbital signs suggest post-septal infection and require urgent imaging and IV antibiotics.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient has sudden sensorineural hearing loss over 24 hours. Management?","options":["Urgent ENT assessment and early corticosteroid consideration","Antihistamine only","Wait six months","Routine wax removal"],"answer":0,"explanation":"Sudden sensorineural loss is time sensitive and warrants prompt specialist assessment.","pearl":"Sudden sensorineural loss is time sensitive and warrants prompt specialist assessment.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient has fever, drooling, muffled voice and tripod positioning. Priority?","options":["Send unescorted for CT","Keep calm and arrange expert airway team","Force oropharyngeal examination","Discharge"],"answer":1,"explanation":"Suspected epiglottitis can deteriorate rapidly; avoid provoking airway obstruction.","pearl":"Suspected epiglottitis can deteriorate rapidly; avoid provoking airway obstruction.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient with peritonsillar abscess has trismus and uvular deviation. Management?","options":["Immediate tonsillectomy for all","Drainage assessment plus antibiotics","Routine antivirals only","Observe without review"],"answer":1,"explanation":"Quinsy often requires drainage and antimicrobial treatment with airway assessment.","pearl":"Quinsy often requires drainage and antimicrobial treatment with airway assessment.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient has sudden flashes, floaters and curtain-like visual field loss. Diagnosis?","options":["Conjunctivitis","Retinal detachment","Uveitis","Acute glaucoma"],"answer":1,"explanation":"Retinal detachment warrants urgent ophthalmological evaluation.","pearl":"Retinal detachment warrants urgent ophthalmological evaluation.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient with posterior epistaxis remains unstable despite anterior packing. Next?","options":["Discharge","Resuscitate and urgent ENT haemorrhage control","Routine CT in a month","Oral antihistamine"],"answer":1,"explanation":"Uncontrolled posterior epistaxis may need specialist packing, embolisation or surgery.","pearl":"Uncontrolled posterior epistaxis may need specialist packing, embolisation or surgery.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient has painful swollen ear after piercing through cartilage. Common concern?","options":["Perichondritis requiring antipseudomonal assessment","Otitis media","Mastoiditis only","Cerumen impaction"],"answer":0,"explanation":"Cartilage piercing infections can involve Pseudomonas and cause deformity.","pearl":"Cartilage piercing infections can involve Pseudomonas and cause deformity.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"Psychiatry & Other","question":"A patient on antipsychotics has fever, rigidity, autonomic instability and high CK. Diagnosis?","options":["Serotonin syndrome","Simple anxiety","Opioid withdrawal","Neuroleptic malignant syndrome"],"answer":3,"explanation":"NMS causes severe rigidity and hyperthermia following dopamine blockade.","pearl":"NMS causes severe rigidity and hyperthermia following dopamine blockade.","reference":"Local emergency mental health and specialty guidelines"},{"topic":"Psychiatry & Other","question":"A severely agitated patient is hyperthermic and acidotic after stimulant use. Priority?","options":["Rapid sedation, cooling and supportive resuscitation","Discharge","Beta blocker as sole treatment","Physical restraint alone"],"answer":0,"explanation":"Stimulant toxicity can cause hyperthermia and rhabdomyolysis; supportive control is urgent.","pearl":"Stimulant toxicity can cause hyperthermia and rhabdomyolysis; supportive control is urgent.","reference":"Local emergency mental health and specialty guidelines"},{"topic":"Psychiatry & Other","question":"A patient with alcohol dependence has tremor, tachycardia and hallucinations after cessation. Treatment?","options":["Flumazenil","Discharge","Antipsychotic alone","Benzodiazepine-based withdrawal management"],"answer":3,"explanation":"Benzodiazepines are first-line for significant alcohol withdrawal; give thiamine when indicated.","pearl":"Benzodiazepines are first-line for significant alcohol withdrawal; give thiamine when indicated.","reference":"Local emergency mental health and specialty guidelines"},{"topic":"Psychiatry & Other","question":"A patient with severe agitation and confusion has a fluctuating level of attention. Diagnosis?","options":["Malingering","Primary psychosis always","Dementia only","Delirium"],"answer":3,"explanation":"Acute fluctuating inattention suggests delirium and mandates medical assessment.","pearl":"Acute fluctuating inattention suggests delirium and mandates medical assessment.","reference":"Local emergency mental health and specialty guidelines"},{"topic":"Psychiatry & Other","question":"A patient presents after intentional overdose and denies current suicidal ideation. Next?","options":["Discharge solely on denial","Avoid safety planning","Comprehensive psychosocial risk assessment after medical stabilisation","No collateral history"],"answer":2,"explanation":"Risk assessment must consider circumstances, history, collateral and supports.","pearl":"Risk assessment must consider circumstances, history, collateral and supports.","reference":"Local emergency mental health and specialty guidelines"},{"topic":"Psychiatry & Other","question":"A patient with carbon monoxide exposure has headache and confusion but normal pulse oximetry. Why?","options":["Only anaemia matters","Oximeter is always broken","CO does not cause hypoxia","Pulse oximetry cannot distinguish oxyhaemoglobin from carboxyhaemoglobin"],"answer":3,"explanation":"Conventional pulse oximetry can be falsely reassuring in CO poisoning.","pearl":"Conventional pulse oximetry can be falsely reassuring in CO poisoning.","reference":"Local emergency mental health and specialty guidelines"},{"topic":"Psychiatry & Other","question":"A patient with acute limb ischaemia has pain, pallor and absent pulses. Priority?","options":["Compression bandage","Discharge","Routine outpatient ultrasound","Immediate vascular consultation and anticoagulation if appropriate"],"answer":3,"explanation":"Acute limb ischaemia is time critical and needs urgent vascular management.","pearl":"Acute limb ischaemia is time critical and needs urgent vascular management.","reference":"Local emergency mental health and specialty guidelines"},{"topic":"Psychiatry & Other","question":"A patient with septic arthritis of the knee has fever and a large effusion. Diagnostic test?","options":["Wait for blood cultures","Plain radiograph alone","Urgent joint aspiration","Serum urate only"],"answer":2,"explanation":"Synovial analysis and culture are key; antibiotics and drainage follow promptly.","pearl":"Synovial analysis and culture are key; antibiotics and drainage follow promptly.","reference":"Local emergency mental health and specialty guidelines"},{"topic":"Psychiatry & Other","question":"A patient with hot swollen first MTP and fever may have gout. What must not be missed?","options":["Septic arthritis","Osteoarthritis","Plantar fasciitis","Neuropathy"],"answer":0,"explanation":"Crystal arthritis and infection can coexist; assess for septic arthritis.","pearl":"Crystal arthritis and infection can coexist; assess for septic arthritis.","reference":"Local emergency mental health and specialty guidelines"},{"topic":"Psychiatry & Other","question":"A patient with back pain, fever and a new neurological deficit has high ESR. Priority?","options":["Discharge","Oral NSAID alone","Urgent MRI for spinal infection","Routine physiotherapy"],"answer":2,"explanation":"Spinal epidural abscess requires urgent imaging and specialist management.","pearl":"Spinal epidural abscess requires urgent imaging and specialist management.","reference":"Local emergency mental health and specialty guidelines"},{"topic":"Cardiology","question":"A patient with STEMI and shock has clear lungs, raised JVP and ST elevation V4R. Which drug is most likely to worsen hypotension?","options":["Oxygen if hypoxaemic","Urgent PCI","Cautious crystalloid","IV glyceryl trinitrate"],"answer":3,"explanation":"Nitrates reduce preload and can precipitate severe hypotension in RV infarction.","pearl":"Nitrates reduce preload and can precipitate severe hypotension in RV infarction.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A patient with syncope has QTc 570 ms and polymorphic VT twisting around baseline. Immediate drug?","options":["IV magnesium sulfate","Adenosine","Verapamil","Digoxin"],"answer":0,"explanation":"Torsades de pointes warrants magnesium and correction of precipitants; shock if unstable.","pearl":"Torsades de pointes warrants magnesium and correction of precipitants; shock if unstable.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Cardiology","question":"A patient with pericarditis has fever, large effusion and suspected purulent fluid. Priority?","options":["Exercise testing","Urgent drainage and IV antibiotics","NSAIDs only","Discharge"],"answer":1,"explanation":"Purulent pericarditis requires drainage and antimicrobial treatment.","pearl":"Purulent pericarditis requires drainage and antimicrobial treatment.","reference":"ESC acute coronary syndrome and arrhythmia guidance"},{"topic":"Respiratory","question":"A patient has a tension pneumothorax and profound hypotension. Which finding is least necessary before treatment?","options":["Unilateral reduced breath sounds","Shock","Tracheal deviation","Respiratory distress"],"answer":2,"explanation":"Tracheal deviation is a late and insensitive sign; do not delay decompression.","pearl":"Tracheal deviation is a late and insensitive sign; do not delay decompression.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"A patient with pulmonary embolism develops shock and RV dilatation. Consider?","options":["Systemic thrombolysis if eligible","Routine diuresis","Outpatient DOAC without observation","Antibiotics"],"answer":0,"explanation":"High-risk PE with haemodynamic collapse may require reperfusion therapy.","pearl":"High-risk PE with haemodynamic collapse may require reperfusion therapy.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Respiratory","question":"A patient with known asthma has severe wheeze and is not improving with repeated inhaled bronchodilators. Useful adjunct?","options":["Montelukast as rescue","Furosemide","Routine antibiotics","IV magnesium sulfate"],"answer":3,"explanation":"IV magnesium may be used in severe refractory asthma alongside steroids and bronchodilators.","pearl":"IV magnesium may be used in severe refractory asthma alongside steroids and bronchodilators.","reference":"BTS respiratory guidance; GINA asthma strategy"},{"topic":"Toxicology","question":"A patient has paracetamol overdose and uncertain ingestion time with elevated ALT. Management?","options":["Wait for symptoms","Discharge if asymptomatic","Start acetylcysteine while investigating","Use flumazenil"],"answer":2,"explanation":"When timing is uncertain and toxicity possible, commence NAC while assessing levels and liver injury.","pearl":"When timing is uncertain and toxicity possible, commence NAC while assessing levels and liver injury.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient with ethylene glycol poisoning has severe acidosis and calcium oxalate crystals. Antidote?","options":["Atropine","N-acetylcysteine","Fomepizole","Naloxone"],"answer":2,"explanation":"Fomepizole blocks toxic alcohol metabolism; dialysis may be required.","pearl":"Fomepizole blocks toxic alcohol metabolism; dialysis may be required.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Toxicology","question":"A patient with anticholinergic poisoning has dry skin, mydriasis, urinary retention and delirium. First-line general management?","options":["Activated charcoal days later","Atropine","Naloxone routinely","Supportive care and benzodiazepines for agitation"],"answer":3,"explanation":"Supportive care and temperature control are central; physostigmine is reserved for selected cases.","pearl":"Supportive care and temperature control are central; physostigmine is reserved for selected cases.","reference":"TOXBASE / local Poisons Centre guidance"},{"topic":"Paediatrics","question":"A child with suspected epiglottitis is sitting upright, drooling and distressed. Safest action?","options":["Send alone for X-ray","Avoid upsetting child and call expert airway team","Lay child flat","Force tongue-depressor examination"],"answer":1,"explanation":"Maintain calm and plan controlled airway management to avoid precipitating obstruction.","pearl":"Maintain calm and plan controlled airway management to avoid precipitating obstruction.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"A 3-month-old has fever 39.2 C and appears toxic. Best approach?","options":["Routine steroids","Discharge on antipyretic alone","Delay until urine culture returns","Urgent sepsis assessment and parenteral antibiotics"],"answer":3,"explanation":"Toxic young infants require prompt evaluation and empiric treatment.","pearl":"Toxic young infants require prompt evaluation and empiric treatment.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Paediatrics","question":"A child has severe dehydration, hypernatraemia and shock. Initial fluid?","options":["No fluid until sodium normal","Rapid free-water bolus","Dextrose 5% alone","Isotonic crystalloid bolus with reassessment"],"answer":3,"explanation":"Restore circulation with isotonic fluid, then correct hypernatraemia carefully.","pearl":"Restore circulation with isotonic fluid, then correct hypernatraemia carefully.","reference":"RCH Melbourne clinical practice guidelines"},{"topic":"Trauma","question":"A patient has penetrating thoracic injury and massive ongoing chest tube blood loss. Priority?","options":["Routine outpatient CT","Urgent thoracic surgical haemorrhage control","Clamp chest tube indefinitely","Observation"],"answer":1,"explanation":"Major ongoing intrathoracic haemorrhage requires operative consultation and resuscitation.","pearl":"Major ongoing intrathoracic haemorrhage requires operative consultation and resuscitation.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A patient with unstable pelvic fracture continues bleeding despite binder and resuscitation. Consider?","options":["Oral tranexamic acid","Remove binder and mobilise","Routine discharge","Pelvic angioembolisation or packing"],"answer":3,"explanation":"Persistent pelvic haemorrhage requires definitive interventional or operative control.","pearl":"Persistent pelvic haemorrhage requires definitive interventional or operative control.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Trauma","question":"A trauma patient is hypothermic, acidotic and coagulopathic. Which principle improves outcomes?","options":["Damage-control resuscitation with haemorrhage control","Large volumes of cold saline","Allow hypothermia","Delay blood products"],"answer":0,"explanation":"Prevent the lethal triad using balanced resuscitation, warming and rapid source control.","pearl":"Prevent the lethal triad using balanced resuscitation, warming and rapid source control.","reference":"ATLS principles; local major trauma guidelines"},{"topic":"Neurology","question":"A patient with sudden severe headache, neck stiffness and CT-confirmed SAH develops hydrocephalus. Priority?","options":["High-dose anticoagulation","Urgent neurosurgical assessment for CSF diversion","Routine outpatient MRI","Discharge"],"answer":1,"explanation":"Acute hydrocephalus after SAH can require emergency external ventricular drainage.","pearl":"Acute hydrocephalus after SAH can require emergency external ventricular drainage.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient has new unilateral headache, jaw claudication and visual loss at age 76. Treatment?","options":["Observation","Immediate high-dose glucocorticoids","Oral antibiotics","Wait for temporal artery biopsy"],"answer":1,"explanation":"Suspected giant cell arteritis with visual symptoms requires immediate steroids to prevent blindness.","pearl":"Suspected giant cell arteritis with visual symptoms requires immediate steroids to prevent blindness.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Neurology","question":"A patient has ascending weakness, urinary retention and a sensory level. Investigation?","options":["No imaging","Routine CT head","Outpatient EMG only","Urgent MRI spine"],"answer":3,"explanation":"A sensory level and sphincter dysfunction suggest spinal cord pathology needing urgent MRI.","pearl":"A sensory level and sphincter dysfunction suggest spinal cord pathology needing urgent MRI.","reference":"AHA/ASA stroke guidance; local neurology pathways"},{"topic":"Infectious Diseases","question":"A patient with bacterial meningitis has purpura fulminans and shock. Organism of concern?","options":["Giardia","Candida albicans","Rhinovirus","Neisseria meningitidis"],"answer":3,"explanation":"Meningococcaemia can cause purpura fulminans and rapidly progressive shock.","pearl":"Meningococcaemia can cause purpura fulminans and rapidly progressive shock.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"A patient with infective endocarditis develops acute pulmonary oedema and new severe regurgitation. Priority?","options":["Urgent cardiothoracic assessment","Discharge on oral antibiotics","Outpatient echo","Exercise testing"],"answer":0,"explanation":"Valve destruction and acute heart failure are indications for urgent surgical assessment.","pearl":"Valve destruction and acute heart failure are indications for urgent surgical assessment.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Infectious Diseases","question":"A patient with sepsis has a fluctuant abscess and persistent fever despite antibiotics. Essential management?","options":["Escalate oral antibiotics only","Incision and drainage","Steroids","No intervention"],"answer":1,"explanation":"Drainage is essential source control for a drainable abscess.","pearl":"Drainage is essential source control for a drainable abscess.","reference":"Therapeutic Guidelines: Antibiotic; local sepsis guidelines"},{"topic":"Gastroenterology","question":"A patient has a strangulated bowel obstruction with peritonitis and rising lactate. Next?","options":["Nasogastric tube only then discharge","Oral laxatives","Outpatient colonoscopy","Urgent surgery"],"answer":3,"explanation":"Strangulation and peritonitis mandate urgent operative management.","pearl":"Strangulation and peritonitis mandate urgent operative management.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient with severe ulcerative colitis has toxic megacolon and perforation. Priority?","options":["Discharge","Loperamide","High-fibre diet","Emergency surgical consultation"],"answer":3,"explanation":"Perforated toxic megacolon requires urgent surgery and resuscitation.","pearl":"Perforated toxic megacolon requires urgent surgery and resuscitation.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Gastroenterology","question":"A patient with acute cholecystitis develops septic shock and is unfit for surgery. Consider?","options":["Discharge","Percutaneous cholecystostomy for source control","Oral antacid","Colonoscopy"],"answer":1,"explanation":"Drainage can provide source control when surgery is not feasible in critically ill patients.","pearl":"Drainage can provide source control when surgery is not feasible in critically ill patients.","reference":"Gastroenterology society guidelines; local surgical pathways"},{"topic":"Renal & Metabolic","question":"A patient has severe hyperkalaemia despite calcium, insulin and salbutamol with renal failure. Next?","options":["Oral potassium","Discharge","Urgent dialysis consideration","Repeat calcium indefinitely as sole therapy"],"answer":2,"explanation":"Refractory hyperkalaemia in renal failure may require dialysis for potassium removal.","pearl":"Refractory hyperkalaemia in renal failure may require dialysis for potassium removal.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient with DKA has glucose fallen to 13 mmol/L but persistent ketoacidosis. Next?","options":["Give glucagon","Stop insulin immediately","Discharge","Continue insulin and add dextrose-containing fluids"],"answer":3,"explanation":"Insulin must continue until ketoacidosis resolves, with dextrose to prevent hypoglycaemia.","pearl":"Insulin must continue until ketoacidosis resolves, with dextrose to prevent hypoglycaemia.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"Renal & Metabolic","question":"A patient with SIADH has sodium 119 but no severe symptoms. Which strategy is generally appropriate?","options":["Routine desmopressin alone","Controlled fluid restriction and cause treatment","Rapid normalisation with hypertonic saline","Large hypotonic boluses"],"answer":1,"explanation":"Chronic non-severe SIADH is usually managed gradually, avoiding rapid correction.","pearl":"Chronic non-severe SIADH is usually managed gradually, avoiding rapid correction.","reference":"KDIGO guidance; local metabolic emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient with eye pain after grinding metal has a high-velocity projectile history. Avoid?","options":["Urgent ophthalmology","CT orbit","MRI until metallic intraocular foreign body excluded","Eye shield"],"answer":2,"explanation":"MRI may move ferromagnetic intraocular foreign bodies and should be avoided.","pearl":"MRI may move ferromagnetic intraocular foreign bodies and should be avoided.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"ENT & Ophthalmology","question":"A patient has acute vision loss, afferent pupillary defect and painful eye movements. Consider?","options":["Presbyopia","Simple conjunctivitis","Optic neuritis","Blepharitis"],"answer":2,"explanation":"Painful monocular vision loss with RAPD suggests optic neuritis and needs assessment.","pearl":"Painful monocular vision loss with RAPD suggests optic neuritis and needs assessment.","reference":"RANZCOG not applicable; local ENT and ophthalmology emergency protocols"},{"topic":"Psychiatry & Other","question":"A patient taking clozapine has fever, chest pain and tachycardia early in treatment. Concern?","options":["Tension headache","Simple anxiety","BPPV","Myocarditis"],"answer":3,"explanation":"Clozapine-associated myocarditis is potentially fatal and requires urgent assessment.","pearl":"Clozapine-associated myocarditis is potentially fatal and requires urgent assessment.","reference":"Local emergency mental health and specialty guidelines"}];
